// Hand-curated cookie knowledge that is NOT in the Open Cookie Database
// (lib/utils/cookie_db.g.dart, generated by tool/gen_cookie_db.dart).
//
// Policy: for a name that is in OCD, OCD wins. Only names missing from OCD
// live here, plus [forcedCategory] for the rare name where OCD is clearly
// wrong for this app's purpose. test/utils/cookie_db_test.dart fails if an
// override duplicates an OCD name.
//
// Shape: name -> (category, provider, wildcard). wildcard = true matches every
// cookie name starting with the key (keys of 3+ characters only).

import 'package:view_source_vibe/utils/cookie_utils.dart';

